CREATE TABLE strategy_versions (id bigserial PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), config jsonb NOT NULL);
CREATE TABLE markets (id text PRIMARY KEY,slug text UNIQUE NOT NULL,question text NOT NULL,category text NOT NULL,rules text NOT NULL,end_date timestamptz,raw jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE market_price_history (id bigserial PRIMARY KEY,market_id text NOT NULL REFERENCES markets,observed_at timestamptz NOT NULL,exchange_at text,book jsonb NOT NULL);
CREATE INDEX market_history_recent ON market_price_history(market_id,observed_at DESC);
CREATE TABLE research_runs (id bigserial PRIMARY KEY,market_id text NOT NULL REFERENCES markets,strategy_id bigint NOT NULL REFERENCES strategy_versions,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),analysis jsonb NOT NULL,probability numeric(12,10) NOT NULL CHECK(probability BETWEEN 0 AND 1),confidence numeric(12,10) NOT NULL CHECK(confidence BETWEEN 0 AND 1),quality numeric(12,10) NOT NULL CHECK(quality BETWEEN 0 AND 1),disagreement numeric(12,10) NOT NULL CHECK(disagreement BETWEEN 0 AND 1));
CREATE TABLE research_sources(id bigserial PRIMARY KEY,research_id bigint NOT NULL REFERENCES research_runs,url text NOT NULL,title text NOT NULL,evidence jsonb NOT NULL);
CREATE TABLE analyst_predictions(id bigserial PRIMARY KEY,research_id bigint NOT NULL REFERENCES research_runs,analyst text NOT NULL,model text NOT NULL,prediction jsonb NOT NULL);
CREATE TABLE portfolio (id integer PRIMARY KEY CHECK(id=1),cash numeric(24,6) NOT NULL CHECK(cash>=0),starting_cash numeric(24,6) NOT NULL CHECK(starting_cash=1000));
INSERT INTO portfolio VALUES (1,1000,1000);
CREATE TABLE simulated_orders(id bigserial PRIMARY KEY,idempotency_key text UNIQUE NOT NULL,market_id text NOT NULL REFERENCES markets,research_id bigint NOT NULL REFERENCES research_runs,strategy_id bigint NOT NULL REFERENCES strategy_versions,book_id bigint NOT NULL REFERENCES market_price_history,side text NOT NULL CHECK(side IN ('LONG','SHORT')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),decision jsonb NOT NULL);
CREATE TABLE simulated_fills(id bigserial PRIMARY KEY,order_id bigint NOT NULL REFERENCES simulated_orders,price numeric(12,10) NOT NULL CHECK(price>0 AND price<1),quantity numeric(24,6) NOT NULL CHECK(quantity>0),notional numeric(24,6) NOT NULL CHECK(notional>0),fee numeric(24,6) NOT NULL CHECK(fee>=0),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE positions(id bigserial PRIMARY KEY,order_id bigint UNIQUE NOT NULL REFERENCES simulated_orders,market_id text NOT NULL REFERENCES markets,category text NOT NULL,correlation_group text NOT NULL,side text NOT NULL CHECK(side IN('LONG','SHORT')),quantity numeric(24,6) NOT NULL CHECK(quantity>0),cost numeric(24,6) NOT NULL CHECK(cost>0),opened_at timestamptz NOT NULL DEFAULT clock_timestamp(),closed_at timestamptz,payout numeric(24,6),realized_pnl numeric(24,6));
CREATE UNIQUE INDEX one_open_position ON positions(market_id) WHERE closed_at IS NULL;
CREATE TABLE market_resolutions(market_id text PRIMARY KEY REFERENCES markets,payout numeric(12,10) NOT NULL CHECK(payout BETWEEN 0 AND 1),observed_at timestamptz NOT NULL DEFAULT clock_timestamp(),evidence jsonb NOT NULL);
CREATE TABLE portfolio_snapshots(id bigserial PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),cash numeric(24,6) NOT NULL,equity numeric(24,6) NOT NULL,open_value numeric(24,6) NOT NULL,stale_marks boolean NOT NULL);
CREATE TABLE system_jobs(id bigserial PRIMARY KEY,kind text NOT NULL,market_id text REFERENCES markets,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),status text NOT NULL,detail jsonb NOT NULL);
CREATE TABLE audit_events(id bigserial PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),kind text NOT NULL,payload jsonb NOT NULL,previous_hash text NOT NULL,hash text UNIQUE NOT NULL);
CREATE TABLE login_attempts(bucket text PRIMARY KEY,attempts integer NOT NULL,window_start timestamptz NOT NULL);
CREATE FUNCTION forbid_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Immutable history'; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['strategy_versions','market_price_history','research_runs','research_sources','analyst_predictions','simulated_orders','simulated_fills','market_resolutions','portfolio_snapshots','audit_events','system_jobs'] LOOP EXECUTE format('CREATE TRIGGER immutable_record BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION forbid_mutation()',t); END LOOP; END $$;
